async () => {
  const out = [];
  for (let p = 1; p <= 17; p++) {
    const f = document.forms[0];
    const fd = new URLSearchParams(new FormData(f));
    fd.set('__EVENTTARGET','gv'); fd.set('__EVENTARGUMENT','Page$'+p);
    const r = await fetch('/Devices.aspx',{method:'POST',body:fd,headers:{'Content-Type':'application/x-www-form-urlencoded'}});
    const d = new DOMParser().parseFromString(await r.text(),'text/html');
    [...d.querySelectorAll('tr')].map(t=>t.innerText?.replace(/\s+/g,' ').trim()||t.textContent.replace(/\s+/g,' ').trim()).filter(t=>/^\d+ D\d+/.test(t)).forEach(t=>out.push(t));
  }
  return out.filter(t=>/ (1004|1011|1026) /.test(t));
}

