async () => {
  const out = [];
  for (let p = 1; p <= 17; p++) {
    const fd = new URLSearchParams(new FormData(document.forms[0]));
    fd.set('__EVENTTARGET','gv'); fd.set('__EVENTARGUMENT','Page$'+p);
    const r = await fetch('/Devices.aspx',{method:'POST',body:fd,headers:{'Content-Type':'application/x-www-form-urlencoded'}});
    const d = new DOMParser().parseFromString(await r.text(),'text/html');
    d.querySelectorAll('tr').forEach(tr=>{const c=[...tr.children].map(x=>x.textContent.trim()); if(c.length===5&&/^D\d+$/.test(c[1])) out.push(c.slice(0,4).join('|'));});
  }
  return {total: out.length, hits: out.filter(t=>/\|(1004|1011|1026)\|/.test(t))};
}

